const assert = require('node:assert/strict');
const { OrderHandler } = require('../.build/handler');
const { OrderRepository } = require('../.build/repository');

const handler = new OrderHandler(new OrderRepository([
  { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
  { id: 'x', tenant: 'b', createdAt: '2026-01-01', total: 3 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 }
]));
assert.deepEqual(handler.list({ tenant: 'a', limit: 1 }), {
  items: [{ id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 }],
  nextCursor: '2026-01-01|a'
});
assert.deepEqual(handler.list({ tenant: 'a', limit: 1, cursor: '2026-01-01|a' }), {
  items: [{ id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 }],
  nextCursor: null
});

// Freeze both the array and its rows so mutation fails the check.
const rows = Object.freeze([
  { id: 'last', tenant: 'a', createdAt: '2026-01-02', total: 6 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 5 },
  { id: '0', tenant: 'b', createdAt: '2026-01-01', total: 0 },
  { id: '2', tenant: 'a', createdAt: '2026-01-01', total: 3 },
  { id: 'Z', tenant: 'a', createdAt: '2026-01-01', total: 4 },
  { id: '10', tenant: 'a', createdAt: '2026-01-01', total: 2 },
  { id: 'later', tenant: 'b', createdAt: '2026-01-03', total: 7 }
].map(Object.freeze));
const snapshot = JSON.stringify(rows);
const repository = new OrderRepository(rows);
const paginated = new OrderHandler(repository);
assert.deepEqual(repository.list('a').map(row => row.id), ['10', '2', 'Z', 'a', 'last']);

for (const limit of [1, 2, 3, 5, 100]) {
  const ids = [];
  let cursor;
  do {
    const page = paginated.list({ tenant: 'a', limit, cursor });
    ids.push(...page.items.map(row => row.id));
    if (page.nextCursor !== null) {
      const last = page.items.at(-1);
      assert.equal(page.nextCursor, `${last.createdAt}|${last.id}`);
    }
    cursor = page.nextCursor;
  } while (cursor !== null);
  assert.deepEqual(ids, ['10', '2', 'Z', 'a', 'last']);
}

// Resume from a missing/deleted pair, without looking up the cursor row.
assert.deepEqual(paginated.list({ tenant: 'a', limit: 100, cursor: '2026-01-01|3' })
  .items.map(row => row.id), ['Z', 'a', 'last']);
// A cursor from another tenant is still a pair boundary, not a row lookup.
assert.deepEqual(paginated.list({ tenant: 'a', limit: 1, cursor: '2026-01-01|0' }), {
  items: [rows[5]], nextCursor: '2026-01-01|10'
});
assert.deepEqual(paginated.list({ tenant: 'a', limit: 100, cursor: '2026-01-02|last' }), {
  items: [], nextCursor: null
});
assert.deepEqual(paginated.list({ tenant: 'missing', limit: 1 }), {
  items: [], nextCursor: null
});
assert.deepEqual(paginated.list({ tenant: 'a', limit: 1, cursor: '9999|z' }), {
  items: [], nextCursor: null
});
assert.equal(JSON.stringify(rows), snapshot);

for (const limit of [0, -1, 101, 1.5, NaN, Infinity, '1', undefined]) {
  assert.throws(() => handler.list({ tenant: 'a', limit }), { message: 'invalid request' });
}
assert.throws(() => handler.list({ tenant: '', limit: 1 }), { message: 'invalid request' });
for (const cursor of ['', '|', 'date', 'date|', '|id', 'date|id|extra', 'date||id', null, 1]) {
  assert.throws(() => handler.list({ tenant: 'a', limit: 1, cursor }), { message: 'invalid request' });
}

