import { OrderRepository } from './repository';
import { ListRequest, Page } from './types';
export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}
  list(request: ListRequest): Page {
    if (!request.tenant || !Number.isInteger(request.limit) || request.limit < 1 || request.limit > 100) {
      throw new Error('invalid request');
    }
    let after: { createdAt: string; id: string } | undefined;
    if (request.cursor !== undefined) {
      if (typeof request.cursor !== 'string') {
        throw new Error('invalid request');
      }
      const parts = request.cursor.split('|');
      if (parts.length !== 2 || !parts[0] || !parts[1]) {
        throw new Error('invalid request');
      }
      after = { createdAt: parts[0], id: parts[1] };
    }
    const rows = this.repository.list(request.tenant, after);
    const items = rows.slice(0, request.limit);
    const last = items[items.length - 1];
    return {
      items,
      nextCursor: rows.length > request.limit ? `${last.createdAt}|${last.id}` : null
    };
  }
}

